import {useCatalogWithoutPacks} from './audio-catalog-fixture.js';
import {test,expect} from '@playwright/test';import {freshState} from '../../src/engine.js';import {scenarioContent} from '../../src/scenario-content.js';
for(const direction of ['ko-ja','ja-ko'])for(const width of [320,390])test(`5-7 repair feedback resume completion ${direction} ${width}`,async({page})=>{
 await page.setViewportSize({width,height:width===320?640:844});await page.addInitScript(s=>{if(!localStorage.getItem('seodang.web-prototype.v1'))localStorage.setItem('seodang.web-prototype.v1',JSON.stringify(s));localStorage.setItem('seodang.analytics.v1',JSON.stringify({consent:false,queue:[]}));},{...freshState(),onboarded:true,courseDirection:direction,onboardingLevel:7,koreanGuideSeenVersion:1,settings:{sound:false,motion:'off',textScale:1.2,audioRate:1}});
 await useCatalogWithoutPacks(page);
 const enter=()=>page.locator('.map-choice[data-id="11"][data-action="scenario"]').click();await page.goto('/playable.html');await enter();await expect(page.locator('.app-header-title')).toContainText('7.');await expect(page.locator('main')).toHaveClass(/lesson-top/);await page.locator('[data-action="scenario-next"]').click();
 const layout=async()=>{expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1)).toBe(true);for(const row of await page.locator('.repair-page .audio-text-row').all()){const b=await row.evaluate(e=>({text:e.querySelector('p').getBoundingClientRect().right,speaker:e.querySelector('button').getBoundingClientRect().left}));expect(b.speaker).toBeGreaterThanOrEqual(b.text-1);}const tops=await page.locator('.repair-page>.button-pair>button').evaluateAll(es=>es.map(e=>e.getBoundingClientRect().top));expect(Math.abs(tops[0]-tops[1])).toBeLessThan(2);};
 for(let i=0;i<3;i++){
  const x=scenarioContent[direction]['11'].items[i];await expect(page.locator('[data-model-answer]')).toHaveText(x.answer);await page.locator('[data-action="scenario-next"]').click();await expect(page.locator('.repair-original .audio-text-row p')).toHaveText(x.text);await expect(page.locator('[data-action="scenario-check"]')).toBeDisabled();await layout();
  if(i===0)await page.evaluate(()=>scrollTo(0,0));if(i===0)await page.screenshot({path:`output/repair-choose-${direction}-${width}-${test.info().project.name}.png`,fullPage:true});
  const wrong=(i+1)%3,feedbackIndex=wrong>i?wrong-1:wrong;await page.locator(`[data-action="scenario-select"][data-id="${wrong}"]`).click();
  if(i===0){await page.reload();await enter();await page.locator('[data-choice="resume"]').click();await expect(page.locator('[data-action="scenario-select"][data-id="1"]')).toHaveAttribute('aria-pressed','true');}
  await page.locator('[data-action="scenario-check"]').click();await expect(page.locator('aside.scenario-feedback')).toContainText(x.othersFeedback[feedbackIndex]);await expect(page.locator('.repair-result')).toHaveCount(0);await layout();
  await page.locator(`[data-action="scenario-select"][data-id="${i}"]`).click();await page.locator('[data-action="scenario-check"]').click();await expect(page.locator('.repair-result .audio-text-row p')).toHaveText(x.answer);await expect(page.locator('.repair-result .scenario-feedback')).toHaveText(x.hint);await page.locator('.repair-result details summary').click();await expect(page.locator('.repair-result details p')).toHaveText(x.answerMeaning);await layout();
  if(i===0)await page.evaluate(()=>scrollTo(0,0));if(i===0)await page.screenshot({path:`output/repair-result-${direction}-${width}-${test.info().project.name}.png`,fullPage:true});
  await page.locator('[data-action="scenario-next"]').click();
 }
 await expect(page.locator('.practice-fireworks svg')).toBeVisible();await page.locator('[data-action="completed-next"]').click();await expect(page.locator('.practice-complete')).toHaveCount(0);await page.reload();await expect(page.locator('.map-choice[data-id="11"][data-action="scenario"]').locator('..')).toHaveClass(/is-complete/);
});
